            <!-- noite + degradês para legibilidade -->
            <div class="eg-abs eg-noite" style="inset:0"></div>
            <div class="eg-abs" style="left:0;right:0;top:0;height:96px;background:linear-gradient(rgba(18,20,20,.92),rgba(18,20,20,0));pointer-events:none"></div>
            <div class="eg-abs" style="left:0;right:0;bottom:0;height:190px;background:linear-gradient(rgba(18,20,20,0),rgba(18,20,20,.9));pointer-events:none"></div>

            <!-- título, sininho e selos -->
            <div class="eg-cab">
              <h1 class="titulo-aba sem-sub">In&iacute;cio</h1>
              <button type="button" class="eg-sino" id="btnSino" aria-haspopup="dialog" aria-expanded="false" aria-controls="modalAtencao" aria-label="Pontos de aten&ccedil;&atilde;o">
                <svg data-lucide="bell"></svg><span class="eg-sino-num" id="sinoNum" hidden>0</span>
              </button>
            </div>
            <div class="eg-selos selos-status">
              <span class="selo-status" id="seloConexao"><i></i><span>verificando…</span></span>
              <span class="selo-status neutro" id="seloFase"><svg data-lucide="sprout"></svg><span>--</span></span>
              <span class="selo-status neutro" id="seloLuz"><svg data-lucide="sun"></svg><span><span class="skeleton" id="luzContagem">--</span><span id="luzLegenda"></span></span></span>
            </div>

            <!-- aviso quando o ESP32 não responde -->
            <div class="eg-sem-dados" id="egSemDados" role="status" hidden><svg data-lucide="wifi-off"></svg><span id="egSemDadosTxt">Sem dados do ESP32</span></div>

            <!-- leituras sobrepostas -->
            <div class="eg-leituras">
