              <div class="eg-chip" data-estagio="germinacao"><svg width="28" height="28" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 30h22"/><path d="M18 30V21"/><path d="M18 22c-4.5 0-6.5-2.5-6.5-5.5 4 0 6.5 2 6.5 5.5zM18 22c3.5 0 5.5-2 5.5-5-3.5 0-5.5 1.8-5.5 5z"/></svg><span>Germinação</span><small id="egDia-germinacao">&nbsp;</small></div><div class="eg-chip" data-estagio="muda"><svg width="28" height="28" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 31h22"/><path d="M18 31V13"/><path d="M18 24c-5 0-7-3-7-6 4.5 0 7 2.5 7 6zM18 20c4.5 0 6.5-2.5 6.5-5.5-4 0-6.5 2.2-6.5 5.5zM18 14c0-3 1.5-5 3.5-6.5"/></svg><span>Muda</span><small id="egDia-muda">&nbsp;</small></div><div class="eg-chip" data-estagio="vegetativo"><svg width="28" height="28" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 32h22"/><path d="M18 32V6"/><path d="M18 27c-5 0-8-3-8-6 5 0 8 2.5 8 6zM18 27c5 0 8-3 8-6-5 0-8 2.5-8 6zM18 19c-4.5 0-7-2.5-7-5.5 4.5 0 7 2 7 5.5zM18 19c4.5 0 7-2.5 7-5.5-4.5 0-7 2-7 5.5z"/></svg><span>Vegetação</span><small id="egDia-vegetativo">&nbsp;</small></div><div class="eg-chip" data-estagio="floracao"><svg width="28" height="28" viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 32h22"/><path d="M18 32V14"/><path d="M18 27c-5 0-8-3-8-6 5 0 8 2.5 8 6zM18 27c5 0 8-3 8-6-5 0-8 2.5-8 6z"/><ellipse cx="18" cy="8.5" rx="3.5" ry="6"/></svg><span>Floração</span><small id="egDia-floracao">&nbsp;</small></div>
